def is_safe(board, row, col):
    for i in range(row):
        if board[i] == col or \
           abs(board[i] - col) == abs(i - row):
            return False
    return True

def solve_n_queens(n, fixed_row, fixed_col):
    board = [-1] * n
    board[fixed_row] = fixed_col

    def backtrack(row):
        if row == n:
            return True
        if row == fixed_row:
            return backtrack(row + 1)

        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    else:
        return None

solution = solve_n_queens(5, 1, 2)
print(solution)
